  let r = cast[ptr LcnRsInstance](dst)
  r[] = LcnRsInstance()
  let f11 = v.lookup("failure")
  if f11.isSome:
    r.failure = Opt.some(default(LcnRsFailure))
    w.later(stepDecLcnRsFailure, f11.get, addr r.failure.get)
  r.instance = v.lookup("instance").get.text
  let f12 = v.lookup("intent").get
  w.later(stepDecLcnRsInstanceIntentChoice, f12, addr r.intent)
  let f13 = v.lookup("intent_revision")
