  let f16 = v.lookup("record").get
  w.later(stepDecLcnRsRecord, f16, addr r.record)
  r.revision = uint64(v.lookup("revision").get.uint)
  let f17 = v.lookup("source").get
  w.later(stepDecLcnRsInstanceSourceChoice, f17, addr r.source)
  let f18 = v.lookup("state").get
  w.later(stepDecLcnRsInstanceStateChoice, f18, addr r.state)

