proc stepEncLcnRsRecord*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnRsRecord](src)
  var n = 2
  if x.configuration_commitment.isSome:
    inc n
  if x.implements.isSome:
    inc n
  if x.primary_contract.isSome:
    inc n
  if x.requested_permissions.isSome:
    inc n
  if x.requires.isSome:
    inc n
  if x.state_assignment.isSome:
    inc n
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](n))
  dst[] = node
  var k = 0
  if x.configuration_commitment.isSome:
    node.entries[k].key = cbor("configuration_commitment")
    node.entries[k].value = cbor(x.configuration_commitment.get)
    inc k
  node.entries[k].key = cbor("implementation")
  w.later(stepEncLcnRsImplementation, addr x.implementation, addr node.entries[k].value)
  inc k
  if x.implements.isSome:
    node.entries[k].key = cbor("implements")
    let a22 = newCborArray(x.implements.get.len)
    node.entries[k].value = a22
    for i23 in 0 ..< x.implements.get.len:
      w.later(stepEncSchemaCommitment, addr x.implements.get[i23], addr a22.items[i23])
    inc k
  node.entries[k].key = cbor("module")
  node.entries[k].value = cbor(x.module)
  inc k
  if x.primary_contract.isSome:
    node.entries[k].key = cbor("primary_contract")
    w.later(stepEncSchemaCommitment, addr x.primary_contract.get, addr node.entries[k].value)
    inc k
  if x.requested_permissions.isSome:
    node.entries[k].key = cbor("requested_permissions")
    let a27 = newCborArray(x.requested_permissions.get.len)
    node.entries[k].value = a27
    for i28 in 0 ..< x.requested_permissions.get.len:
      w.later(stepEncLcnRsPermission, addr x.requested_permissions.get[i28], addr a27.items[i28])
    inc k
  if x.requires.isSome:
    node.entries[k].key = cbor("requires")
    let a31 = newCborArray(x.requires.get.len)
    node.entries[k].value = a31
    for i32 in 0 ..< x.requires.get.len:
      w.later(stepEncLcnRsRequirement, addr x.requires.get[i32], addr a31.items[i32])
    inc k
  if x.state_assignment.isSome:
    node.entries[k].key = cbor("state_assignment")
    node.entries[k].value = cbor(x.state_assignment.get)
    inc k

proc stepDecLcnRsRecord*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnRsRecord](dst)
  r[] = LcnRsRecord()
  let f20 = v.lookup("configuration_commitment")
  if f20.isSome:
    r.configuration_commitment = Opt.some(f20.get.bytes)
  let f21 = v.lookup("implementation").get
  w.later(stepDecLcnRsImplementation, f21, addr r.implementation)
  let f24 = v.lookup("implements")
  if f24.isSome:
    r.implements = Opt.some(default(seq[SchemaCommitment]))
    r.implements.get.setLen(f24.get.items.len)
    for i25 in 0 ..< f24.get.items.len:
      w.later(stepDecSchemaCommitment, f24.get.items[i25], addr r.implements.get[i25])
  r.module = v.lookup("module").get.text
  let f26 = v.lookup("primary_contract")
  if f26.isSome:
    r.primary_contract = Opt.some(default(SchemaCommitment))
    w.later(stepDecSchemaCommitment, f26.get, addr r.primary_contract.get)
  let f29 = v.lookup("requested_permissions")
  if f29.isSome:
    r.requested_permissions = Opt.some(default(seq[LcnRsPermission]))
    r.requested_permissions.get.setLen(f29.get.items.len)
    for i30 in 0 ..< f29.get.items.len:
      w.later(stepDecLcnRsPermission, f29.get.items[i30], addr r.requested_permissions.get[i30])
  let f33 = v.lookup("requires")
  if f33.isSome:
    r.requires = Opt.some(default(seq[LcnRsRequirement]))
    r.requires.get.setLen(f33.get.items.len)
    for i34 in 0 ..< f33.get.items.len:
      w.later(stepDecLcnRsRequirement, f33.get.items[i34], addr r.requires.get[i34])
  let f35 = v.lookup("state_assignment")
  if f35.isSome:
    r.state_assignment = Opt.some(f35.get.text)

proc toCbor*(x: LcnRsRecord): CborValue =
  runEnc(stepEncLcnRsRecord, addr x)

proc fromChecked*(T: type LcnRsRecord, v: CborValue): LcnRsRecord =
  var r: LcnRsRecord
  runDec(stepDecLcnRsRecord, v, addr r)
  r

proc stepEncLcnRsRequirementCardinalityChoice*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnRsRequirementCardinalityChoice](src)
  case x.kind
  of LcnRsRequirementCardinalityChoiceKind.All_runtime_visible:
    dst[] = cbor("all-runtime-visible")
  of LcnRsRequirementCardinalityChoiceKind.Single:
    dst[] = cbor("single")

proc stepDecLcnRsRequirementCardinalityChoice*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnRsRequirementCardinalityChoice](dst)
  case generatedSchema().arm("lcn.rs_requirement#cardinality", v)
  of 0:
    r[] = LcnRsRequirementCardinalityChoice(kind: LcnRsRequirementCardinalityChoiceKind.Single)
  of 1:
    r[] = LcnRsRequirementCardinalityChoice(kind: LcnRsRequirementCardinalityChoiceKind.All_runtime_visible)
  else:
    raiseAssert "a checked value selects a known arm"

