  r

proc stepEncLcnRsRequirement*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnRsRequirement](src)
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](2))
  dst[] = node
  var k = 0
  node.entries[k].key = cbor("cardinality")
  w.later(stepEncLcnRsRequirementCardinalityChoice, addr x.cardinality, addr node.entries[k].value)
  inc k
  node.entries[k].key = cbor("contract")
  w.later(stepEncSchemaCommitment, addr x.contract, addr node.entries[k].value)
  inc k

proc stepDecLcnRsRequirement*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnRsRequirement](dst)
  r[] = LcnRsRequirement()
  let f36 = v.lookup("cardinality").get
  w.later(stepDecLcnRsRequirementCardinalityChoice, f36, addr r.cardinality)
  let f37 = v.lookup("contract").get
  w.later(stepDecSchemaCommitment, f37, addr r.contract)

