proc stepEncLcnRsState*(w: var EncWork, src: pointer, dst: ptr CborValue) =
  let x {.used.} = cast[ptr LcnRsState](src)
  let node = CborValue(kind: ckMap, entries: newSeq[CborEntry](6))
  dst[] = node
  var k = 0
  node.entries[k].key = cbor("create_keys")
  let a39 = newCborArray(x.create_keys.len)
  node.entries[k].value = a39
  for i40 in 0 ..< x.create_keys.len:
    w.later(stepEncLcnRsCreateKey, addr x.create_keys[i40], addr a39.items[i40])
  inc k
  node.entries[k].key = cbor("epoch")
  node.entries[k].value = cbor(uint64(x.epoch))
  inc k
  node.entries[k].key = cbor("format")
  node.entries[k].value = cbor("logos-core-nim.runtime-state.v1")
  inc k
  node.entries[k].key = cbor("instances")
  let a43 = newCborArray(x.instances.len)
  node.entries[k].value = a43
  for i44 in 0 ..< x.instances.len:
    w.later(stepEncLcnRsInstance, addr x.instances[i44], addr a43.items[i44])
  inc k
  node.entries[k].key = cbor("retired")
  let a47 = newCborArray(x.retired.len)
  node.entries[k].value = a47
  for i48 in 0 ..< x.retired.len:
    w.later(stepEncLcnRsRetired, addr x.retired[i48], addr a47.items[i48])
  inc k
  node.entries[k].key = cbor("runtime_instance_id")
  node.entries[k].value = cbor(x.runtime_instance_id)
  inc k

proc stepDecLcnRsState*(w: var DecWork, v: CborValue, dst: pointer) =
  let r = cast[ptr LcnRsState](dst)
  r[] = LcnRsState()
  let f41 = v.lookup("create_keys").get
  r.create_keys.setLen(f41.items.len)
  for i42 in 0 ..< f41.items.len:
    w.later(stepDecLcnRsCreateKey, f41.items[i42], addr r.create_keys[i42])
  r.epoch = uint64(v.lookup("epoch").get.uint)
  let f45 = v.lookup("instances").get
  r.instances.setLen(f45.items.len)
  for i46 in 0 ..< f45.items.len:
    w.later(stepDecLcnRsInstance, f45.items[i46], addr r.instances[i46])
  let f49 = v.lookup("retired").get
  r.retired.setLen(f49.items.len)
  for i50 in 0 ..< f49.items.len:
    w.later(stepDecLcnRsRetired, f49.items[i50], addr r.retired[i50])
  r.runtime_instance_id = v.lookup("runtime_instance_id").get.text

